from typing import List

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def find_prime_factors(n):
    factors = []
    i = 2
    while i <= n:
        if n % i == 0 and is_prime(i):
            factors.append(i)
            n = n // i
        else:
            i += 1
    return factors

def count_occurrences(factors):
    occurrences = {}
    for factor in factors:
        if factor in occurrences:
            occurrences[factor] += 1
        else:
            occurrences[factor] = 1
    return occurrences

def factorize(n: int) -> List[int]:
    prime_factors = find_prime_factors(n)
    occurrences = count_occurrences(prime_factors)
    result = []
    for factor, count in occurrences.items():
        result.extend([factor] * count)
    return result

# Test cases
print(factorize(8))  # Output: [2, 2, 2]
print(factorize(25))  # Output: [5, 5]
print(factorize(70))  # Output: [2, 5, 7]

