def right_angle_triangle(a, b, c):
    # Check if the given sides can form a triangle
    if a + b <= c or a + c <= b or b + c <= a:
        return False

    # Find the longest side of the triangle
    hypotenuse = max(a, b, c)

    # Find the sum of squares of the other two sides
    sum_of_squares = a**2 + b**2 + c**2 - hypotenuse**2

    # Check if the square of 'hypotenuse' is equal to 'sum_of_squares'
    if hypotenuse**2 == sum_of_squares:
        return True
    else:
        return False

